previewCss:
.darma-loader-darma-b11-thermometer { --accent: var(--loader-color, #f97316); --accent-2: var(--loader-secondary-color, #ef4444); width: calc(var(--loader-size, 108px) * .34); height: var(--loader-size, 108px); position: relative; display: grid; place-items: start center; }
.darma-loader-darma-b11-thermometer .darma-loader-darma-b11-thermometer__tube { position: relative; width: 40%; height: 74%; margin-top: 4%; background: #e2e8f0; border-radius: 20px; overflow: hidden; box-shadow: inset 0 0 0 2px #cbd5e1; }
.darma-loader-darma-b11-thermometer .darma-loader-darma-b11-thermometer__tube::after { content: ''; position: absolute; left: 0; bottom: 0; width: 100%; background: linear-gradient(var(--accent), var(--accent-2)); animation: darma-loader-darma-b11-thermometer-mercury calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b11-thermometer::after { content: ''; position: absolute; bottom: 2%; left: 50%; width: calc(var(--loader-size, 108px) * .28); height: calc(var(--loader-size, 108px) * .28); margin-left: calc(var(--loader-size, 108px) * -.14); border-radius: 50%; background: var(--accent-2); box-shadow: inset 0 0 0 2px #cbd5e1; }
@keyframes darma-loader-darma-b11-thermometer-mercury { 0% { height: 8%; } 50% { height: 100%; } 100% { height: 8%; } }

